// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }

    function testFuzz_property(uint256 seed, address caller) public {
        // The caller must be the current CEO for DrugDealer to succeed.
        vm.assume(caller == c.ceoAddress());

        // Drive c through DrugDealer from the current CEO.
        vm.prank(caller);
        c.DrugDealer();

        // General rule: after a successful DrugDealer call, ceoAddress equals
        // the caller and is never the zero address.
        assertTrue(c.ceoAddress() == caller && c.ceoAddress() != address(0));
    }
}
